export const LOAN_PLANS={rescueFast:{name:'急救',period:15,rate:.06,terms:3},rescue:{name:'翻盘',period:30,rate:.10,terms:3},rescueLong:{name:'背水一战',period:60,rate:.14,terms:3},fast:{name:'急借',period:30,rate:.15,terms:3},standard:{name:'周转',period:60,rate:.10,terms:3},long:{name:'长周期',period:120,rate:.08,terms:3}};
export const cents=v=>Math.round(v*100)/100;
export function loanBook(){return {active:null,borrowed:0,repaid:0,interestPaid:0,default:null};}
export function accrue(book,time){const l=book.active;if(!l||time<=l.lastAccrued)return;const growth=Math.pow(1+l.rate,(time-l.lastAccrued)/(l.period*60000));l.interest+=(l.principal+l.interest)*(growth-1);l.lastAccrued=time;}
export function debt(book,time){const l=book.active;if(!l)return 0;return cents((l.principal+l.interest)*Math.pow(1+l.rate,Math.max(0,time-l.lastAccrued)/(l.period*60000)));}
export function createLoan(book,amount,key,time){if(book.active)throw Error('请先还清当前借款，不能叠加借款');if(!Number.isFinite(amount)||amount<500000||amount>2000000||amount%10000)throw Error('借款为1万日元整数倍，范围50万–200万日元');const plan=LOAN_PLANS[key];if(!plan)throw Error('借款方案无效');const growth=Math.pow(1+plan.rate,plan.terms);const installment=Math.ceil(amount*plan.rate*growth/(growth-1)*100)/100;const l={...plan,key,original:amount,principal:amount,interest:0,lastAccrued:time,start:time,nextDue:time+plan.period*60000,paidTerms:0,installment};book.active=l;book.borrowed=cents(book.borrowed+amount);return l;}
export function creditPayment(book,amount,time){accrue(book,time);const l=book.active;if(!l)throw Error('当前没有借款');const full=debt(book,time);if(!Number.isFinite(amount)||amount<=0||amount>full+.005)throw Error('还款金额无效或超过当前欠款');amount=cents(amount);const interest=Math.min(amount,l.interest);l.interest-=interest;l.principal=Math.max(0,l.principal-(amount-interest));book.repaid=cents(book.repaid+amount);book.interestPaid=cents(book.interestPaid+interest);if(amount>=full-.005)book.active=null;return amount;}

